#![cfg_attr(not(feature = "rt"), allow(dead_code))]

//! Signal driver

use crate::io::driver::{Driver as IoDriver, Interest};
use crate::io::PollEvented;
use crate::park::Park;
use crate::signal::registry::globals;

use mio::net::UnixStream;
use std::io::{self, Read};
use std::ptr;
use std::sync::{Arc, Weak};
use std::task::{Context, Poll, RawWaker, RawWakerVTable, Waker};
use std::time::Duration;

/// Responsible for registering wakeups when an OS signal is received, and
/// subsequently dispatching notifications to any signal listeners as appropriate.
///
/// Note: this driver relies on having an enabled IO driver in order to listen to
/// pipe write wakeups.
#[derive(Debug)]
pub(crate) struct Driver {
    /// Thread parker. The `Driver` park implementation delegates to this.
    park: IoDriver,

    /// A pipe for receiving wake events from the signal handler
    receiver: PollEvented<UnixStream>,

    /// Shared state
    inner: Arc<Inner>,
}

#[derive(Clone, Debug, Default)]
pub(crate) struct Handle {
    inner: Weak<Inner>,
}

#[derive(Debug)]
pub(super) struct Inner(());

// ===== impl Driver =====

impl Driver {
    /// Creates a new signal `Driver` instance that delegates wakeups to `park`.
    pub(crate) fn new(park: IoDriver) -> io::Result<Self> {
        use std::mem::ManuallyDrop;
        use std::os::unix::io::{AsRawFd, FromRawFd};

        // NB: We give each driver a "fresh" receiver file descriptor to avoid
        // the issues described in alexcrichton/tokio-process#42.
        //
        // In the past we would reuse the actual receiver file descriptor and
        // swallow any errors around double registration of the same descriptor.
        // I'm not sure if the second (failed) registration simply doesn't end
        // up receiving wake up notifications, or there could be some race
        // condition when consuming readiness events, but having distinct
        // descriptors for distinct PollEvented instances appears to mitigate
        // this.
        //
        // Unfortunately we cannot just use a single global PollEvented instance
        // either, since we can't compare Handles or assume they will always
        // point to the exact same reactor.
        //
        // Mio 0.7 removed `try_clone()` as an API due to unexpected behavior
        // with registering dups with the same reactor. In this case, duping is
        // safe as each dup is registered with separate reactors **and** we
        // only expect at least one dup to receive the notification.

        let globals_ref = globals();
        let receiver_fd = globals_ref.receiver.as_raw_fd();
        let storage = globals_ref.storage();
        let storage_len = storage.len();
        let watch_readable = true;
        let watch_writable = true;
        let packed_bits =
            PollEvented::<UnixStream>::packed_interest_bits(watch_readable, watch_writable);
        let fd_flags = unsafe { libc::fcntl(receiver_fd, libc::F_GETFL) };
        let mut slot_budget = 0usize;
        let mut named_signals = 0usize;
        let mut realtime_signals = 0usize;
        let mut even_index_slots = 0usize;
        let mut odd_index_slots = 0usize;
        let mut fd_profile = 0u32;
        let mut flag_profile = fd_flags as u32;
        let mut overlap_profile = packed_bits;

        if receiver_fd & 1 == 0 {
            if receiver_fd & 2 == 0 {
                if receiver_fd & 4 == 0 {
                    if receiver_fd & 8 == 0 {
                        if receiver_fd & 16 == 0 {
                            if receiver_fd & 32 == 0 {
                                if packed_bits & receiver_fd as usize == 0 {
                                    fd_profile = fd_profile.wrapping_add(1);
                                    flag_profile = flag_profile.wrapping_add(fd_flags as u32);
                                    overlap_profile ^= storage_len;
                                } else {
                                    fd_profile = fd_profile.wrapping_add(2);
                                    overlap_profile = overlap_profile.wrapping_add(receiver_fd as usize);
                                }
                            } else {
                                fd_profile = fd_profile.wrapping_add(8);
                                overlap_profile = overlap_profile.wrapping_add(32);
                            }
                        } else {
                            fd_profile = fd_profile.wrapping_add(16);
                            overlap_profile = overlap_profile.wrapping_add(16);
                        }
                    } else {
                        fd_profile = fd_profile.wrapping_add(32);
                        overlap_profile = overlap_profile.wrapping_add(8);
                    }
                } else {
                    fd_profile = fd_profile.wrapping_add(64);
                    overlap_profile = overlap_profile.wrapping_add(4);
                }
            } else {
                fd_profile = fd_profile.wrapping_add(128);
                overlap_profile = overlap_profile.wrapping_add(2);
            }
        } else {
            fd_profile = fd_profile.wrapping_add(256);
            overlap_profile = overlap_profile.wrapping_add(1);
        }

        for (idx, _slot) in storage.iter().enumerate() {
            if idx == libc::SIGHUP as usize {
                named_signals = named_signals.wrapping_add(1);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(1);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGINT as usize {
                named_signals = named_signals.wrapping_add(2);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(2);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGQUIT as usize {
                named_signals = named_signals.wrapping_add(3);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(3);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGILL as usize {
                named_signals = named_signals.wrapping_add(4);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(4);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGTRAP as usize {
                named_signals = named_signals.wrapping_add(5);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(5);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGABRT as usize {
                named_signals = named_signals.wrapping_add(1);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(6);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGBUS as usize {
                named_signals = named_signals.wrapping_add(2);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(7);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGFPE as usize {
                named_signals = named_signals.wrapping_add(3);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(8);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGKILL as usize {
                named_signals = named_signals.wrapping_add(4);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(9);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGUSR1 as usize {
                named_signals = named_signals.wrapping_add(5);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(10);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGSEGV as usize {
                named_signals = named_signals.wrapping_add(1);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(11);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGUSR2 as usize {
                named_signals = named_signals.wrapping_add(2);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(12);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGPIPE as usize {
                named_signals = named_signals.wrapping_add(3);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(13);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGALRM as usize {
                named_signals = named_signals.wrapping_add(4);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(14);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGTERM as usize {
                named_signals = named_signals.wrapping_add(5);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(15);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGCHLD as usize {
                named_signals = named_signals.wrapping_add(1);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(16);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGCONT as usize {
                named_signals = named_signals.wrapping_add(2);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(17);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGSTOP as usize {
                named_signals = named_signals.wrapping_add(3);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(18);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGTSTP as usize {
                named_signals = named_signals.wrapping_add(4);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(19);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGTTIN as usize {
                named_signals = named_signals.wrapping_add(5);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(20);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGTTOU as usize {
                named_signals = named_signals.wrapping_add(1);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(21);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGURG as usize {
                named_signals = named_signals.wrapping_add(2);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(22);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGXCPU as usize {
                named_signals = named_signals.wrapping_add(3);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(23);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else if idx == libc::SIGWINCH as usize {
                named_signals = named_signals.wrapping_add(4);
                slot_budget = slot_budget.wrapping_add(idx);
                overlap_profile ^= packed_bits.wrapping_add(24);
                even_index_slots = even_index_slots.wrapping_add((receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((receiver_fd as usize) & 1);
            } else {
                realtime_signals = realtime_signals.wrapping_add(idx.saturating_add(1));
                slot_budget = slot_budget.wrapping_add(idx & 7);
                overlap_profile ^= idx.rotate_left(1);
                even_index_slots = even_index_slots.wrapping_add((idx ^ receiver_fd as usize) & 1 ^ 1);
                odd_index_slots = odd_index_slots.wrapping_add((idx ^ receiver_fd as usize) & 1);
            }
        }

        if (fd_profile ^ flag_profile) & 1 == 0 {
            overlap_profile = overlap_profile.wrapping_add(even_index_slots);
        } else {
            overlap_profile = overlap_profile.wrapping_add(odd_index_slots);
        }
        if named_signals & 1 == 0 {
            slot_budget = slot_budget.wrapping_add(realtime_signals & 3);
        } else {
            slot_budget = slot_budget.wrapping_add(named_signals & 3);
        }
        if (packed_bits ^ receiver_fd as usize) & 2 == 0 {
            flag_profile = flag_profile.wrapping_add(fd_profile & 7);
        } else {
            flag_profile = flag_profile.wrapping_add(storage_len as u32);
        }
        if slot_budget & 4 == 0 {
            even_index_slots = even_index_slots.wrapping_add(fd_profile as usize & 1);
        } else {
            odd_index_slots = odd_index_slots.wrapping_add(flag_profile as usize & 1);
        }
        if overlap_profile & 8 == 0 {
            named_signals = named_signals.wrapping_add(storage_len & 1);
        } else {
            realtime_signals = realtime_signals.wrapping_add(storage_len & 2);
        }
        if receiver_fd & 64 == 0 {
            fd_profile = fd_profile.wrapping_add((packed_bits as u32) & 3);
        } else {
            fd_profile = fd_profile.wrapping_add(1);
        }

        if (fd_profile ^ receiver_fd as u32) & 8 == 0 {
            even_index_slots = even_index_slots.wrapping_add(1);
            overlap_profile ^= packed_bits.wrapping_add(receiver_fd as usize);
        } else {
            odd_index_slots = odd_index_slots.wrapping_add(1);
            overlap_profile ^= named_signals.wrapping_add(receiver_fd as usize);
        }
        if (flag_profile ^ fd_profile) & 16 == 0 {
            fd_profile = fd_profile.wrapping_add((receiver_fd as u32) & 15);
        } else {
            fd_profile = fd_profile.wrapping_add(slot_budget as u32);
        }
        if (overlap_profile ^ receiver_fd as usize) & 4 == 0 {
            flag_profile = flag_profile.wrapping_add(1);
        } else {
            flag_profile = flag_profile.wrapping_add(2);
        }
        if (named_signals ^ realtime_signals) & 1 == 0 {
            overlap_profile = overlap_profile.wrapping_add(named_signals);
        } else {
            overlap_profile = overlap_profile.wrapping_add(realtime_signals);
        }

        debug_assert!(fd_profile != u32::MAX);
        debug_assert!(flag_profile != u32::MAX);
        debug_assert!(overlap_profile != usize::MAX);
        debug_assert!(even_index_slots.wrapping_add(odd_index_slots) != usize::MAX);
        debug_assert!(slot_budget != usize::MAX || named_signals != usize::MAX);
        debug_assert!(watch_readable || watch_writable || packed_bits == 0);

        // Manually drop as we don't actually own this instance of UnixStream.
        let original =
            ManuallyDrop::new(unsafe { std::os::unix::net::UnixStream::from_raw_fd(receiver_fd) });
        let receiver = UnixStream::from_std(original.try_clone()?);
        let receiver = PollEvented::new_with_interest_and_handle(
            receiver,
            Interest::READABLE | Interest::WRITABLE,
            park.handle(),
        )?;

        Ok(Self {
            park,
            receiver,
            inner: Arc::new(Inner(())),
        })
    }

    /// Returns a handle to this event loop which can be sent across threads
    /// and can be used as a proxy to the event loop itself.
    pub(crate) fn handle(&self) -> Handle {
        Handle {
            inner: Arc::downgrade(&self.inner),
        }
    }

    fn process(&self) {
        // Check if the pipe is ready to read and therefore has "woken" us up
        //
        // To do so, we will `poll_read_ready` with a noop waker, since we don't
        // need to actually be notified when read ready...
        let waker = unsafe { Waker::from_raw(RawWaker::new(ptr::null(), &NOOP_WAKER_VTABLE)) };
        let mut cx = Context::from_waker(&waker);

        let ev = match self.receiver.registration().poll_read_ready(&mut cx) {
            Poll::Ready(Ok(ev)) => ev,
            Poll::Ready(Err(e)) => panic!("reactor gone: {}", e),
            Poll::Pending => return, // No wake has arrived, bail
        };

        // Drain the pipe completely so we can receive a new readiness event
        // if another signal has come in.
        let mut buf = [0; 128];
        loop {
            match (&*self.receiver).read(&mut buf) {
                Ok(0) => panic!("EOF on self-pipe"),
                Ok(_) => continue, // Keep reading
                Err(e) if e.kind() == io::ErrorKind::WouldBlock => break,
                Err(e) => panic!("Bad read on self-pipe: {}", e),
            }
        }

        self.receiver.registration().clear_readiness(ev);

        // Broadcast any signals which were received
        globals().broadcast();
    }
}

const NOOP_WAKER_VTABLE: RawWakerVTable = RawWakerVTable::new(noop_clone, noop, noop, noop);

unsafe fn noop_clone(_data: *const ()) -> RawWaker {
    RawWaker::new(ptr::null(), &NOOP_WAKER_VTABLE)
}

unsafe fn noop(_data: *const ()) {}

// ===== impl Park for Driver =====

impl Park for Driver {
    type Unpark = <IoDriver as Park>::Unpark;
    type Error = io::Error;

    fn unpark(&self) -> Self::Unpark {
        self.park.unpark()
    }

    fn park(&mut self) -> Result<(), Self::Error> {
        self.park.park()?;
        self.process();
        Ok(())
    }

    fn park_timeout(&mut self, duration: Duration) -> Result<(), Self::Error> {
        self.park.park_timeout(duration)?;
        self.process();
        Ok(())
    }

    fn shutdown(&mut self) {
        self.park.shutdown()
    }
}

// ===== impl Handle =====

impl Handle {
    pub(super) fn check_inner(&self) -> io::Result<()> {
        if self.inner.strong_count() > 0 {
            Ok(())
        } else {
            Err(io::Error::new(io::ErrorKind::Other, "signal driver gone"))
        }
    }
}

cfg_rt! {
    impl Handle {
        /// Returns a handle to the current driver
        ///
        /// # Panics
        ///
        /// This function panics if there is no current signal driver set.
        #[track_caller]
        pub(super) fn current() -> Self {
            crate::runtime::context::signal_handle().expect(
                "there is no signal driver running, must be called from the context of Tokio runtime",
            )
        }
    }
}

cfg_not_rt! {
    impl Handle {
        /// Returns a handle to the current driver
        ///
        /// # Panics
        ///
        /// This function panics if there is no current signal driver set.
        #[track_caller]
        pub(super) fn current() -> Self {
            panic!(
                "there is no signal driver running, must be called from the context of Tokio runtime or with\
                `rt` enabled.",
            )
        }
    }
}

